// ─── EXCEL EXPORTS ───────────────────────────────────────────────────────────

function downloadExcel(b64data, filename) {
  const bytes = atob(b64data);
  const ab = new ArrayBuffer(bytes.length);
  const ua = new Uint8Array(ab);
  for (let i = 0; i < bytes.length; i++) ua[i] = bytes.charCodeAt(i);
  const blob = new Blob([ab], {type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}
const EXCEL_DATA = {
  phase1: "",
  phase2: "",
  phase3: "",
  phase4: "",
};
function downloadPhase1Excel() { downloadExcel(EXCEL_DATA.phase1, "nordicfoods_phase1_hypothesis.xlsx"); }
function downloadPhase2Excel() { downloadExcel(EXCEL_DATA.phase2, "nordicfoods_phase2_factpack.xlsx"); }
function downloadPhase3Excel() { downloadExcel(EXCEL_DATA.phase3, "nordicfoods_phase3_scenarios.xlsx"); }
function downloadPhase4Excel() { downloadExcel(EXCEL_DATA.phase4, "nordicfoods_phase4_landing.xlsx"); }

